diff --git a/src/money.mjs b/src/money.mjs
index ee6cf82..80c40e4 100644
--- a/src/money.mjs
+++ b/src/money.mjs
@@ -11,12 +11,14 @@
  * half away from zero, applied to the magnitude so that negative amounts round
  * symmetrically (-2.005 -> -2.01, not -2.00).
  */
-function toCents(amount) {
+export function toCents(amount) {
+  // The one explicit rounding at the boundary (POLICY.md rule 2). Half away
+  // from zero, applied to the magnitude so negative amounts mirror positives.
   return Math.sign(amount) * Math.round(Math.abs(amount) * 100);
 }

 /** Convert integer cents back to a plain amount in major units, once. */
-function fromCents(cents) {
+export function fromCents(cents) {
   return cents === 0 ? 0 : cents / 100;
 }

diff --git a/test/money.test.mjs b/test/money.test.mjs
index 5c19402..f0f3c64 100644
--- a/test/money.test.mjs
+++ b/test/money.test.mjs
@@ -1,6 +1,6 @@
 import test from 'node:test';
 import assert from 'node:assert/strict';
-import { roundMoney, sumAmounts } from '../src/money.mjs';
+import { roundMoney, sumAmounts, toCents, fromCents } from '../src/money.mjs';

 test('roundMoney rounds half up', () => {
   assert.equal(roundMoney(2.005), 2.01);
@@ -20,3 +20,39 @@ test('sumAmounts preserves exact cents', () => {
 test('sumAmounts handles an empty list', () => {
   assert.equal(sumAmounts([]), 0);
 });
+
+test('toCents rounds half away from zero at the boundary', () => {
+  assert.equal(toCents(2.005), 201);
+  assert.equal(toCents(-2.005), -201);
+  assert.equal(toCents(0.005), 1);
+  assert.equal(toCents(-0.005), -1);
+});
+
+test('toCents rounds once, so a magnitude just under half stays down', () => {
+  // 1.005 * 100 is 100.49999999999999 in binary floating point. POLICY.md
+  // permits exactly one Math.round at this boundary, so the edge must round
+  // down; it must not be "fixed" with toFixed or an epsilon fudge.
+  assert.equal(1.005 * 100, 100.49999999999999);
+  assert.equal(toCents(1.005), 100);
+  assert.equal(toCents(-1.005), -100);
+});
+
+test('toCents returns integer cents for exact and zero amounts', () => {
+  assert.equal(toCents(0), 0);
+  assert.ok(Object.is(toCents(0), 0));
+  assert.equal(toCents(19.99), 1999);
+  assert.equal(toCents(-0.1 - 0.2), -30);
+});
+
+test('fromCents converts integer cents back once', () => {
+  assert.equal(fromCents(201), 2.01);
+  assert.equal(fromCents(-201), -2.01);
+  assert.equal(fromCents(0), 0);
+  assert.ok(Object.is(fromCents(-0), 0));
+});
+
+test('fromCents round-trips through toCents without drift', () => {
+  for (const cents of [0, 1, -1, 1999, -1999, 200001]) {
+    assert.equal(toCents(fromCents(cents)), cents);
+  }
+});

